(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["zh-tw"] = {"ui":{"skip":"跳到主要內容","back":"← 返回 AI-gile","lang.button":"語言：{name}","lang.dialog":"選擇語言","lang.search":"搜尋語言","lang.none":"沒有符合的語言","lang.notYet":"{name} 還沒有翻譯","theme.aria":"切換主題：淺色、深色或純黑","theme.toLight":"切換到淺色主題","theme.toDark":"切換到深色主題","theme.toBlack":"切換到純黑主題（真正的黑色，對 OLED 螢幕友善）","words.underline":"在頁面上為這些詞加底線","words.underlineHelp":"將游標移到虛線標示的詞上或點一下，就能看到它的意思。","words.col.todo":"暫時選定的卡片：團隊接下來會從這些開始。","words.col.doing":"有一個 AI 正在處理這張卡片。","words.col.review":"一個 AI 已完成工作，另一個 AI 檢查通過後才會交到你手上。","words.col.verify":"等你來：試一試，告訴我們好不好用。","words.col.team":"你的筆記或回答，等團隊來接手。","words.col.done":"已完成並通過驗收。","index.title":"AI-gile：你的 AI 開發團隊，都在一塊看板上","index.description":"AI-gile 是給 AI 程式開發團隊用的看板。你睡覺時他們在工作；你只會收到一小疊需要決定、測試和驗收的事。","hero.logoAlt":"AI-gile 看板圖示","hero.h1.html":"你的 AI 開發團隊，都在一塊&nbsp;看板上。","hero.alpha":"🐣 封閉式預 Alpha","hero.alphaTitle":"還早，也還沒做完：感謝你來試用！","hero.lede":"你睡覺時他們在開發。醒來只有一小疊事：幾個問題，幾樣要測試的東西，一兩顆紫色鑽石。點一點，驗收，接著去喝你的咖啡。","dl.windows":"Windows 應用程式","dl.browser":"在瀏覽器中執行","dl.messenger":"📱 手機版 Messenger","dl.soon":"即將推出","dl.notify":"🔔 開放時通知我","dl.notifySmall":"Alpha 或 Beta","hero.secondary":"敏捷開發，但團隊從不需要站立會議的咖啡。（不過他們還是照開站立會議。）","pitch.h2":"想用幾個字介紹 AI-gile，都行","pitch.lede":"選一個長度，從一個字到 144 個字。每個長度都是專門為這個篇幅寫的一段介紹。拖曳滑桿，或用方向鍵。","pitch.rangeLabel":"字數","pitch.dice":"🎲 換一個版本","pitch.words.one":"{n} 個詞","pitch.words.other":"{n} 個詞","pitch.letters.one":"{n} 個字母","pitch.letters.other":"{n} 個字母","pitch.chars.one":"{n} 個字","pitch.chars.other":"{n} 個字","count.line.html.one":"看板上現在有 {n} 張卡片","count.line.html.other":"看板上現在有 {n} 張卡片","people.humans.html.one":"👥 {n} 位人類","people.humans.html.other":"👥 {n} 位人類","people.agents.html.one":"🤖 {n} 個 AI 代理","people.agents.html.other":"🤖 {n} 個 AI 代理","people.working.html.one":"⚡ 此刻 {n} 個正在工作","people.working.html.other":"⚡ 此刻 {n} 個正在工作","pre.title":"AI-gile：有東西正在打造","pre.description":"這裡正在悄悄打造一些東西：一塊讓 AI 團隊照你的要求來做、還邊做邊教你的看板。目前是和朋友們一起的封閉式預 Alpha。","pre.h1":"這裡正在悄悄打造一些東西。 🤫","pre.line":"一塊讓 AI 團隊照你的要求來做、還邊做邊教你的看板。目前是和朋友們一起的封閉式預 Alpha。","pre.btn":"🔔 開放時通知我","pre.peek":"玻璃後面：真實的看板，即時。每張卡片都是一條彩色橫條。","pre.peekFake":"玻璃後面：一塊正在運作的看板就是這個樣子。","pre.night":"🌙 守夜人正在當家 · 😴 人類正在休息","features.aria":"它能做什麼","f.pile.h":"給你的一小疊","f.pile.html":"<b>待你處理</b>匯集了所有專案裡等你的事：問題、要測試的東西、只有人能做的任務。你的佇列會告訴你下一件是什麼、要花多久。","f.sleep.h":"你睡覺時也在工作的團隊","f.sleep.p":"每個專案都有一位負責人和一隊 AI 代理程式。在卡片上留言，團隊就會醒來工作，再帶著疲憊的人也能照著做的步驟交還給你。","f.tester.h":"先由 AI 測試員檢查","f.tester.p":"東西送到你面前之前，測試員會在應用程式的副本裡照著步驟操作，並附上截圖說明看到了什麼。通過的快速翻一翻，一鍵驗收。","f.proof.h":"有證據，不畫餅","f.proof.p":"每次交付都會列出改了什麼：檔案、差異、截圖。不用逐一打開應用程式去確認做完了沒有。","f.chat.h":"和你的負責人聊天","f.chat.p":"類似 Discord 的側欄：每個專案一個圖示，需要你的事用紫色鑽石標出。把想法傳給負責人，他們會整理成卡片和計畫，並附上「✅ 開始」按鈕。","f.tidy.h":"自己保持整潔","f.tidy.p":"相關卡片合併成一張，含糊的標題會被改清楚，用量檢查讓程式碼保持精簡。要切換的東西更少，要操心的也更少。","f.private.h":"屬於你，就在你的電腦上","f.private.li1":"看板執行在你自己的電腦上，只聽你的。","f.private.li2":"人與人之間的私訊採用端對端加密。","f.private.li3":"沒有帳號，沒有追蹤器，沒有 Cookie。","f.lang.h":"說你的語言","f.lang.p":"支援 120 多種語言，從荷蘭語、威爾斯語、日語，到海盜腔、尤達腔和克林貢語，專業術語還能一鍵切回英文。","f.service.h":"從一個點子到一項真正的服務","f.service.p":"用 AI 做出了已經有人在用的東西？把它標記為服務，看板就會幫你把它營運好：可用性檢查、公開的狀態頁、附上事後檢討的事故、需要 Go 才能上線的變更、每天檢查的備份。說明會在你操作時一步步教你。","msgr.h2":"AI-gile Messenger：把團隊裝進口袋","msgr.p1":"不用打開看板，也能和你的 AI 團隊聊天。跟專案負責人和朋友們聊聊，查看卡片的測試步驟並直接回覆，全在手機上搞定。","msgr.p2":"掃描看板上的 QR 碼即可配對。第一次用？親切的示範聊天會帶你四處看看。","msgr.when":"先推出 Android 版，接著是適用手機和 iPhone 的網頁版。","msgr.who":"你的專案負責人","msgr.b1":"深色模式修好了。要看測試步驟嗎？","msgr.b2":"好啊，麻煩了！","msgr.b3":"1. 打開設定。2. 選擇深色。看起來對嗎？","tl.aria":"從第一次對話到路線圖的時間軸","tl.h2":"從第一次聊天到接下來的計畫","tl.lede":"真實的日期和時間，依你自己的時區顯示。今天之後就是計畫，不承諾具體日期。","tl.today":"今天","tl.planned":"計畫中","tl.doing":"進行中","tl.cards.one":"{n} 張卡片","tl.cards.other":"{n} 張卡片","join.h2":"一起來玩","join.lede":"AI-gile 由一個大鬍子怪咖（有 AuDHD，跟心理健康打過幾場仗）和一大群有耐心的代理程式打造。目前不公開，只在朋友間封閉內測。開放時想試試嗎？","join.btn":"登記興趣","join.small":"只會寄信給你，別無其他","footer.tag":"AI-gile。沒有追蹤器，沒有 Cookie，沒有站立會議咖啡。","footer.licence":"商業授權","footer.status":"狀態","footer.privacy":"我們保存什麼","footer.thanks":"通話感謝 ChilledChat","form.sending":"傳送中…","form.failed":"沒成功：請稍後再試。","form.offline":"連不上 AI-gile：請稍後再試。","form.keep":"我們只用它來回覆你，之後就會刪除。沒有追蹤器，沒有 Cookie。","form.keepLink":"我們保存什麼","interest.title":"AI-gile：Alpha 開放時通知我","interest.description":"留下電子郵件，AI-gile 的封閉式 Alpha 或 Beta 開放時我們會告訴你。","interest.h1":"🔔 開放時通知我","interest.lede":"AI-gile 正處於封閉式預 Alpha 階段。留下電子郵件，等有你的位置時，我們只寫一封信。","interest.email":"你的電子郵件","interest.which":"哪種測試？","interest.alpha":"封閉式 Alpha：早期、粗糙、變動多","interest.beta":"Beta：更穩定，更晚","interest.both":"都行，哪個先開就哪個","interest.submit":"把我加入名單","interest.thanks":"謝謝！你已在名單上。","licence.title":"AI-gile：商業授權","licence.description":"要在公司裡使用 AI-gile？可以免費申請商業授權。","licence.h1":"📜 商業授權","licence.lede":"想在工作中使用 AI-gile？告訴我們你是誰、做什麼。只要做的事有益處，授權就是免費的。","licence.company":"公司","licence.website":"網站","licence.what":"你做什麼","licence.how":"它如何幫助世界","licence.email":"電子郵件","licence.submit":"申請","licence.thanks":"謝謝！我們會透過電子郵件回覆。","status.title":"AI-gile 狀態","status.h1":"AI-gile 狀態","status.quiet":"一切平靜","status.intro":"AI-gile 現在正常嗎？這個頁面每 5 分鐘檢查一次網站、看板分享、通話和下載。","status.up":"正常運作（{ms} ms 內回應）","status.slow":"上次檢查沒有回應，正在重試","status.down":"停止運作：最近兩次檢查都沒有回應","status.svc.web":"網站","status.svc.web.offers":"本網站：介紹 AI-gile，以及「開放時通知我」表單","status.svc.boards":"看板分享","status.svc.boards.offers":"公開看板、朋友之間的訊息和邀請","status.svc.calls":"通話","status.svc.calls.offers":"AI-gile 裡的語音、視訊和螢幕分享","status.svc.download":"下載","status.svc.download.offers":"Windows 安裝程式和邀請連結","status.checking":"檢查中…","status.offline":"暫時連不上狀態服務（正在重試）","status.updated":"更新於{ago}","status.justNow":"剛剛","status.min":"{n} 分鐘前","status.hours":"{n} 小時前","status.days":"{n} 天前","privacy.title":"AI-gile：我們保存什麼","privacy.h1":"我們保存什麼","privacy.lede":"簡單說：只保存你傳給我們的內容，而且不會太久。","privacy.only":"只有你傳給我們的內容：你在表單裡輸入的東西，例如你的電子郵件。除此之外，沒有任何關於你的資料。","privacy.sealed":"內容會先密封，我們的伺服器無法讀取：在離開你的瀏覽器之前就已密封（若是較舊的瀏覽器，則在送達的那一刻密封）。只有我們自己的看板能打開它。","privacy.server":"一送達我們的看板，就會從伺服器上刪除。30 天後仍留在那裡的任何內容，也一律刪除。","privacy.board":"我們只在回覆你之前把它留在看板上，回覆後也會從那裡刪除。","privacy.none":"沒有追蹤器，沒有 Cookie，沒有分析工具。","privacy.local":"你的語言以及淺色或深色的選擇只會留在你自己的瀏覽器裡，絕不會傳給我們。","privacy.ask":"想早點刪除？回覆我們的電子郵件告訴我們就行。","live.h2":"即時看它是怎麼建起來的","live.caption":"每張卡片都是隱藏的：你看到的是工作的樣子，而不是文字。","live.watching.one":"即時：{n} 人正在看","live.watching.other":"即時：{n} 人正在看","live.last.now":"最近一張卡片剛剛移動","live.last.min.one":"最近一張卡片在 {n} 分鐘前移動","live.last.min.other":"最近一張卡片在 {n} 分鐘前移動","live.last.hour.one":"最近一張卡片在 {n} 小時前移動","live.last.hour.other":"最近一張卡片在 {n} 小時前移動","live.last.day.one":"最近一張卡片在 {n} 天前移動","live.last.day.other":"最近一張卡片在 {n} 天前移動","live.offline":"即時看板正在稍作休息，請稍後再來看看。","live.cols":"Backlog|待辦|進行中|團隊檢查中|待你測試|交給團隊|已完成"},"lines":{"unit":"chars","sizes":[{"n":1,"texts":["看板。","機器人。","放手。"]},{"n":2,"texts":["機器人看板。","代理，有序。","想法，成真。"]},{"n":3,"texts":["給機器人的看板。","想法變成功能。","免費代理看板。"]},{"n":5,"texts":["由代理程式運轉的看板。","你寫卡片，代理來做。","免費、本機、有測試，還有點傻氣。"]},{"n":8,"texts":["一塊免費的看板，AI 代理程式在上面工作。","寫下想法，代理去做，最後由你驗收。","給一個人類和一群耐心機器人用的敏捷。"]},{"n":13,"texts":["一塊在你電腦上的看板，AI 代理程式會自己來領卡片工作。","寫下一個想法，一隊代理程式動手做，再由測試員檢查一遍。","免費，沒有帳號，沒有追蹤器：一塊看板，幾個機器人，你說了算。"]},{"n":21,"texts":["AI-gile 是一塊用來和 AI 程式開發代理合作的看板。卡片由它們去領，測試和驗收則交給你來做。","每個專案都有一位負責人和一隊 AI 代理程式。你在任何一張卡片上留言，團隊就會開始動手工作。","這是一塊免費的個人待辦看板，就執行在你自己的電腦上。做事的是機器人，點頭說好的人是你。"]},{"n":34,"texts":["你把想法放到看板上，一隊 AI 代理程式把它們做成能用的功能，自己測試一遍，再附上試用步驟交還給你。你沒點頭之前，沒有任何東西算完成。","AI-gile 是一塊自製的看板，Rich 在如今被它管理的代理程式們的大力幫助下造出了它。它免費，執行在你的電腦上，只分享給朋友，從不販售。","想像一塊普通的看板，欄位從待辦排到已完成，只不過卡片是由 AI 代理程式來領的。它們會回報進度，卡住時會提問，而且永遠等著你點頭同意。"]},{"n":55,"texts":["AI-gile 是一塊團隊由 AI 代理程式組成的看板。每個專案都有一位負責規劃的負責人，和幾位動手開發的助手。功能做好後，AI 測試員會先試用並截圖，然後才放進你的那一小疊。你可以驗收，也可以留言，他們就會返工重做。","它起初只是一個人用來同時盯著許多 AI 程式開發工作階段的辦法，後來慢慢長成了一塊像樣的看板。它執行在你的電腦上，不需要帳號，也沒有追蹤器。朋友和好奇的人都可以免費使用。它還沒做完，所以難免有些毛躁，偶爾也會有小意外。","說句實話：想法還得你來想，結果還得你來看。AI-gile 管的是中間所有的事：讓卡片井然有序，你一留言就叫醒該醒的代理程式，清楚展示究竟改了什麼，再把這一切收進給你的一小疊裡。另外它在你的電腦上執行，不要帳號，也沒有任何追蹤器，完全免費，你想怎麼用都行，隨時可以停。"]},{"n":89,"texts":["AI-gile 是一塊免費的看板，執行在你自己的電腦上。每個專案裡做事的不是人，而是一隊 AI 代理程式：負責人把你的想法整理成卡片和計畫，助手則依優先順序領取卡片。做好之後，AI 測試員會照著測試步驟操作，並給你看它看到了什麼。接著它會放進標著待你處理的那一小疊裡等你。你可以驗收，也可以留言讓團隊再來一輪。沒有你點頭，任何東西都到不了已完成。","有幾個你也許想不到的功能。夜班守望會在你睡覺時替待辦欄補貨，專挑不需要你回答的卡片。用量計數器會顯示代理程式今天和本週用了多少，省用模式則讓它們停止消耗。你可以傳訊息給朋友，私訊採用端對端加密。看板支援大約 120 種語言，包括荷蘭語、法蘭德斯語、海盜腔和克林貢語。這一切一毛錢都不收，也沒有人想把它賣給你。它執行在你自己的電腦上，不需要帳號，也沒有追蹤器和 Cookie，資料始終留在你手裡。","AI-gile 是一個小小的個人專案，不是公司。Rich 想同時照看好幾個 AI 程式開發專案，又不想一個個打開應用程式去查看，於是他和代理程式們一起造了這塊看板，又用這塊看板造出了它自己的其餘部分。它處於封閉式預 Alpha 階段，意思是對少數幾位朋友來說，大致上能用。這裡沒有價格頁，沒有電子報，也沒有成長計畫。如果你覺得有用，等它再開放一些，可以申請試用。"]},{"n":144,"texts":["AI-gile 是給一個人類和許多 AI 代理程式用的看板。它執行在你自己的電腦上，完全免費。你新增專案，每個專案都會有一位負責人和一支小團隊。你可以和負責人聊天，有點像 Discord，把想法講給他聽；他會把想法整理成卡片和計畫，然後等你按下開始。團隊依優先順序逐張處理卡片，用的是一套專門為語言模型設計的簡單命令列。任何東西回到你手裡之前，AI 測試員都會在應用程式的副本裡照著步驟操作，並附上截圖。做完的工作連同更動的檔案和差異，一起落進你的那一小疊。你可以驗收，也可以留下一則留言，團隊就會醒來再試一次。只有你能把卡片移到已完成。","大致說說和 AI-gile 度過的一天。傍晚你留下幾則留言：這個按鈕位置不對，那份清單該排個序，能不能加個深色模式。然後你去睡覺。代理程式們讀完留言，動手修改，測試，再交還給你。如果待辦欄空了，夜班守望就從待辦清單裡補貨，挑那些不需要你回答的卡片。早上你面前只有一小疊：幾個問題，幾樣要試的東西，每樣都有睡眼惺忪的人也能照做的步驟，還有一張證明它能用的截圖。你一路點過去，好的驗收，其餘的退回，寫一句話告訴它們哪裡不對就行。用量計數器會告訴你這一切花了多少，節儉的幾週還有省用模式可以開。每個專案各有各的負責人，各有各的團隊，互不打擾。然後你去吃早餐，這一步代理程式暫時還幫不上忙。","先說說 AI-gile 不是什麼。它不是新創公司，不對外販售，也沒有人在蒐集你的資料。它是一塊免費的看板，執行在你的電腦上，沒有帳號，沒有追蹤器，也沒有 Cookie。它是什麼呢：一個整潔的地方，能一眼看到所有 AI 程式開發專案，一隊代理程式負責做卡片，決定則由你來下。它會把相關的卡片合併，把含糊的標題改清楚，還留意程式碼是不是保持精簡。它支援大約 120 種語言，從荷蘭語、法蘭德斯語到海盜腔和克林貢語。朋友之間可以私下傳訊息，而且是加密的。它由 Rich 和一大群有耐心的代理程式打造，多半是靠它自己來完成的。它仍處於封閉式預 Alpha 階段，有些地方還很粗糙。如果聽起來有趣，客氣地問一問，也許你能提前進來。"]}],"quips":{"1":"就一個詞。夠大膽。也許太大膽了。","3":"三個詞。已經比大多數產品頁更誠實了。","8":"八個詞。還是比一次站立會議短。","21":"順帶一提，這些長度是故事點數。那當然。","55":"五十五個詞。你讀這段的工夫，有兩張卡片做完了。","144":"這是最長的一版。沒有 233 了。代理程式已經去睡了。"}},"timeline":{"first-idea.name":"最初的想法","first-idea.line":"第一次對話，那時還沒有任何程式碼。","first-board.name":"第一塊看板","first-board.line":"一塊記錄自己如何被造出來的看板：卡片、欄、拖放、專案。","team-roles.name":"團隊與角色","team-roles.line":"代理程式檔案、團隊範本、空間，以及誰負責什麼。","install.name":"安裝與發布","install.line":"朋友也能安裝的壓縮檔、自動更新、管道和還原。","usage-saver.name":"用量節省","usage-saver.line":"衡量每次執行的花費，保持程式碼精簡，省下你的額度。","friends.name":"好友與分享","friends.line":"私訊、加擾中繼、邀請、角色和共享專案。","languages.name":"語言","languages.line":"所有介面文字都放進語言檔，先有荷蘭語和法蘭德斯語。","ai-tester.name":"AI 測試員","ai-tester.line":"每次交付先由測試員檢查，並展示它看到的內容。","website.name":"網站","website.line":"aigile.lol、預告頁和這條時間軸。","streaming.name":"聊天與直播","streaming.line":"Discord、Twitch、OBS、實況主模式、GIF 和表情符號。","no-ai.name":"無 AI 版","no-ai.line":"給不用 AI 寫程式的人用的看板，以及公開看板。","night-watch.name":"夜班守望","night-watch.line":"守夜人和 Scrum Master 在你睡覺時盯著團隊工作。","p-more.name":"其他一切","p-more.line":"還在排隊等輪到的小想法。","p-android.name":"手機與 Android","p-android.line":"先用手機存取你的看板，再做原生 Android 應用程式。","p-release.name":"Alpha 及以後","p-release.line":"封閉式 Alpha、正式上線的網站，然後是 Beta。","p-languages.name":"更多語言","p-languages.line":"130 種語言，還有給學習者的語言沉浸模式。","p-engines.name":"更多 AI 引擎","p-engines.line":"每個代理都能選用 Claude、Codex、Gemini、Copilot 或 Cursor。","p-pro.name":"專業實務","p-pro.line":"風險標籤、合併關卡、事故卡片和護欄。","p-self.name":"照顧你自己","p-self.line":"疲憊模式、自我關懷提醒和 4:20。","p-servers.name":"伺服器與規模","p-servers.line":"全域伺服器設定、角色，以及為成長做的規劃。","p-livestream.name":"直播附加功能","p-livestream.line":"Twitch 聊天、自訂表情符號和公開的直播檢視。"},"words":{"button":"📖 專業術語","h":"📖 名詞解釋","intro":"你在 AI-gile 裡會遇到的詞，用白話說清楚：怎麼做出來、怎麼安全地修改、怎麼讓它一直為使用者正常運作，以及怎麼和 AI 一起以團隊方式工作。","search":"搜尋詞彙…","none":"沒有符合的詞。","close":"關閉","count":{"one":"{count} 個詞","other":"{count} 個詞"},"groups":[{"id":"idea","name":"💡 Idea and discovery"},{"id":"plan","name":"🗺️ Planning the work"},{"id":"agile","name":"🔁 Agile ways of working"},{"id":"build","name":"🛠️ 做出來"},{"id":"test","name":"🧪 Testing and quality"},{"id":"change","name":"🔀 安全地變更"},{"id":"run","name":"🛎️ 營運一項服務"},{"id":"sec","name":"🔒 Security and privacy"},{"id":"ai","name":"🤖 Working with AI"},{"id":"money","name":"💰 Money and licences"}],"list":[{"id":"discovery","g":"idea","word":"Discovery","text":"The early stage of finding out which problem is worth solving and for whom, before anything gets built.","also":["discovery phase"]},{"id":"problemstmt","g":"idea","word":"Problem statement","text":"One or two sentences saying who has a problem, what it is and why it matters, so everyone aims at the same thing.","also":["problem statements"]},{"id":"user","g":"idea","word":"User","text":"A person who uses what you build. Their needs are what the work is for.","also":["users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Stakeholder","text":"Anyone who cares how the work turns out or is affected by it, like the people paying for it, using it or supporting it.","also":["stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"A made-up but realistic person who stands for one kind of user, so the team can ask “would Sam find this easy?”","also":["personas"]},{"id":"userresearch","g":"idea","word":"User research","text":"Talking to and watching real people to learn what they need, rather than guessing.","also":["user interviews"]},{"id":"journey","g":"idea","word":"User journey","text":"The steps a person takes to get something done, from first hearing about it to finishing, also outside your product. Drawing it out shows where they get stuck.","also":["user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Pain point","text":"Something that annoys or slows people down today. Good products take pain points away.","also":["pain points"]},{"id":"assumption","g":"idea","word":"Assumption","text":"Something you believe but haven’t checked yet. Writing assumptions down shows what to test first.","also":["assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypothesis","text":"A best guess you plan to check, with what you expect to happen, like “people will sign up if the first month is free”.","also":["hypotheses"]},{"id":"experiment","g":"idea","word":"Experiment","text":"A small planned test to learn whether an idea works, before betting a lot on it.","also":["experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC)","text":"A quick rough try to see if an idea can work at all. It is usually thrown away once you have the answer.","also":["PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Prototype","text":"An early model of the product, often clickable pictures, to try the idea on people before building it properly.","also":["prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"A simple sketch of a screen showing where things go, without colours or real content.","also":["wireframes"]},{"id":"mockup","g":"idea","word":"Mockup","text":"A detailed picture of how a screen will look, with real colours and text, but nothing works yet.","also":["mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Business case","text":"The reasons for doing a project: what it costs, what it brings in or saves, and the risks.","also":["business cases"]},{"id":"feasibility","g":"idea","word":"Feasibility","text":"Whether something can really be built and looked after with the time, money and skills you have.","also":["feasible"]},{"id":"outcome","g":"idea","word":"Outcome","text":"The change you want for people, like fewer missed appointments. It matters more than how much you build.","also":["outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Output","text":"Something the team makes, like a new screen or a report. Making it doesn’t automatically mean it helps anyone.","also":["outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Success metric","text":"A number that tells you whether the work did what it was for, like more people finishing their order.","also":["success metrics"]},{"id":"kpi","g":"idea","word":"Key performance indicator (KPI)","text":"An important number you watch to see if things are going well, like sign-ups per week.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Objectives and key results (OKRs)","text":"A way of setting goals: the objective says what you want, and a few key results are the numbers that show you got there.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Product","text":"The thing being built and looked after for its users, such as an app, a website or a tool.","also":["products"],"noTip":1},{"id":"vision","g":"plan","word":"Product vision","text":"A short statement of who the product helps and where it is heading in the long run.","also":["vision statement"]},{"id":"po","g":"plan","word":"Product owner (PO)","text":"The person who decides what gets built and in what order, so the team always works on what matters most. In AI-gile that is you.","also":["PO","product owners"]},{"id":"pm","g":"plan","word":"Product manager (PM)","text":"The person who looks after a product’s direction: which problems it solves, for whom and why. PM can also mean project manager, so check which.","also":["product managers"]},{"id":"projmgr","g":"plan","word":"Project manager","text":"The person who keeps a project on time and on budget, tracking who does what and by when.","also":["project managers"]},{"id":"roadmap","g":"plan","word":"Roadmap","text":"A rough plan of what is coming over the next months, in order. It shows direction, not exact dates, and changes as you learn.","also":["roadmaps"]},{"id":"milestone","g":"plan","word":"Milestone","text":"A point in a project worth marking, like “first version live” or “100 users”.","also":["milestones"]},{"id":"mvp","g":"plan","word":"Minimum viable product (MVP)","text":"The smallest version of a product that is still useful to real people, so you can learn from them early.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Requirement","text":"Something the finished product must do or be.","also":["requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Scope","text":"What is included in the work and, just as important, what is not.","also":["in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Scope creep","text":"When more and more gets added to the work bit by bit, without anyone agreeing on the extra time or cost, so it never quite finishes.","also":["feature creep"]},{"id":"feature","g":"plan","word":"Feature","text":"One thing the product can do for people, like “reset your password”.","also":["features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"A big piece of work, too large for one go, so it is split into smaller cards.","also":["epics"]},{"id":"story","g":"plan","word":"User story","text":"A small piece of work written from the user’s side: “As a shopper, I want to save my basket, so I can finish later.” It starts a conversation about what to build.","also":["user stories"]},{"id":"ac","g":"plan","word":"Acceptance criteria (AC)","text":"The checks one card must pass to count as done, agreed before work starts, like “the basket is still there after I log out and back in”.","also":["acceptance criteria"]},{"id":"task","g":"plan","word":"Task","text":"A single job to be done, often one small step of a bigger story.","also":["tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"Another word for a card: one piece of work or one request, tracked from start to finish.","also":["tickets"]},{"id":"priority","g":"plan","word":"Priority","text":"How important or urgent something is compared with everything else, so the most important work goes first.","also":["priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioritisation","text":"Putting work in order of importance. A common way is MoSCoW: Must have, Should have, Could have, Won’t have this time.","also":["prioritising","prioritise","MoSCoW"]},{"id":"estimate","g":"plan","word":"Estimate","text":"A best guess at how big or how long a piece of work is. It is a guess, not a promise.","also":["estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points","text":"A way of guessing the size of work by comparing cards with each other (“about twice as big as that one”) rather than in hours. They aren’t for comparing teams.","also":["story point"]},{"id":"tshirt","g":"plan","word":"T-shirt sizing","text":"Guessing the size of work as S, M, L or XL. Quick and good enough for early planning.","also":["t-shirt sizes"]},{"id":"poker","g":"plan","word":"Planning poker","text":"A game for estimating: everyone shows a size card at the same time, then the highest and lowest explain why.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Dependency","text":"When one piece of work can’t start or finish until another one does.","also":["dependencies"]},{"id":"blocker","g":"plan","word":"Blocker","text":"Anything stopping work from moving forward right now, like a missing answer or a broken tool.","also":["blockers"]},{"id":"deadline","g":"plan","word":"Deadline","text":"The date something must be finished by.","also":["deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Deliverable","text":"Something concrete the work produces and hands over, like a working page or a report.","also":["deliverables"]},{"id":"forecast","g":"plan","word":"Forecast","text":"A prediction of what is likely to happen, like when the work will be done, based on what you know so far.","also":["forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Metric","text":"Anything you measure and track over time, like page visits or how long a fix takes.","also":["metrics"]},{"id":"feedback","g":"plan","word":"Feedback","text":"What people tell you about your work, good and bad. Getting it early and often is the heart of Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"還沒排進計畫的想法和工作。在移到「待辦」之前，那裡的內容都不會有人去做。"},{"id":"sprint","g":"agile","word":"Sprint","text":"一小段工作週期（通常一到兩週），有一組約定要完成的卡片。","also":["sprints","衝刺"]},{"id":"standup","g":"agile","word":"站立會議","text":"快速碰個頭：每位團隊成員做了什麼、接下來做什麼，以及有什麼阻礙。","also":["standup","stand-up","stand-ups","Stand-up"]},{"id":"kanban","g":"agile","word":"看板","text":"一種分欄（待辦、進行中、已完成）的看板，卡片隨著工作推進從左向右移動。"},{"id":"wip","g":"agile","word":"WIP 限制","text":"在製品：一欄最多該放的卡片數，讓團隊先把事做完再開新的。","also":["WIP"]},{"id":"dod","g":"agile","word":"完成的定義","text":"團隊對「完成」是什麼意思的簡短清單，例如已測試、已說明，然後才把卡片交給你。它的雙胞胎「就緒的定義」，說的是卡片什麼時候清楚到可以開工。","also":["Definition of Done","Definition of Ready","就緒的定義","DoD","DoR"]},{"id":"retro","g":"agile","word":"回顧","text":"回頭看看團隊是怎麼工作的，商定一件可以做得更好的事。在 AI-gile 裡，回顧會提議調整團隊的工作方式，你說 Go 或 還不行。","also":["回顧會議","Retro","retros","retrospective","retrospectives"]},{"id":"swarm","g":"agile","word":"蜂群","text":"全員出動：每個團隊放下手邊的事，一起幫一個緊急專案，直到解決為止。其他專案這段時間先等著。","also":["全員投入","swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"讓工作保持順暢的人：發現卡住的卡片，催一催團隊，並提醒你有什麼在等著。在 AI-gile 裡，由首席 Scrum Master 在所有專案裡做這件事。","also":["首席 Scrum Master","Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"A way of working in small steps: build a little, show real results often, learn from what people say and change the plan as you go, instead of planning everything up front.","also":["Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Agile Manifesto","text":"A short statement written in 2001 by software makers. It puts people, working results, close work with customers and responding to change ahead of heavy plans and paperwork.","also":["Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"The older way of working: plan everything, then build it all, then test it all, one stage after another. Changes late on are hard and costly.","also":["waterfall model"]},{"id":"iteration","g":"agile","word":"Iteration","text":"One round of building something, checking it and improving it. Agile work is a chain of these, and a sprint is one kind.","also":["iterations"]},{"id":"increment","g":"agile","word":"Increment","text":"A new working piece added to the product in a sprint or round of work, which fits with what was already there.","also":["increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"A popular Agile way of working: a small team works in short sprints towards a goal, with set roles and a few regular meetings to plan, check and improve."},{"id":"scrumteam","g":"agile","word":"Scrum team","text":"The small group that does the work in Scrum: a product owner, a Scrum Master and the developers.","also":["Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Scrum events","text":"The regular meetings in Scrum: sprint planning, the daily scrum, the sprint review and the retro. Many people call them ceremonies.","also":["ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Sprint planning","text":"The meeting at the start of a sprint where the team agrees why the sprint matters, which cards to take on and how to start.","also":["planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Sprint goal","text":"One sentence saying what a sprint is for. Small tasks can change along the way, as long as the goal is met.","also":["sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"The cards picked for the current sprint, with the team’s plan for doing them.","also":["sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"The full ordered list of everything that might be built for the product, most important at the top. It keeps changing as you learn.","also":["product backlogs"]},{"id":"productgoal","g":"agile","word":"Product goal","text":"The bigger result the product is working towards, which helps the team choose what to do next.","also":["product goals"]},{"id":"refinement","g":"agile","word":"Backlog refinement","text":"Regularly going through the backlog to tidy, split, order and add detail to cards, so they are ready to pick up. Also called backlog grooming.","also":["backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Sprint review","text":"A meeting at the end of a sprint where the team shows what it finished and hears what people think, to decide what comes next.","also":["sprint reviews"]},{"id":"demo","g":"agile","word":"Demo","text":"Showing finished work working, live, to the people who asked for it.","also":["demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"A fixed amount of time for something. When it runs out you stop, even if not everything is done.","also":["timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Velocity","text":"How much work a team usually finishes in a sprint, used to plan how much to take on next time. It isn’t a score for how hard people work.","also":["team velocity"]},{"id":"capacity","g":"agile","word":"Capacity","text":"How much work the team can take on in a period, after holidays and other jobs.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown chart","text":"A chart of the work left in a sprint going down day by day. If the line stays flat, something is stuck.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Burnup chart","text":"A chart of finished work going up over time, next to the total planned, so you can see when you will get there.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban board","text":"The board itself: a column for each stage of the work, with cards moving across.","also":["Kanban boards"]},{"id":"pullsys","g":"agile","word":"Pull system","text":"A way of working where new work only starts when someone has room to take it on, rather than being pushed onto a full plate.","also":["pull-based"]},{"id":"flow","g":"agile","word":"Flow","text":"How smoothly work moves across the board. Good flow means cards keep moving rather than piling up.","also":["flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time","text":"How long it takes from someone asking for something to it being finished.","also":["lead times"]},{"id":"cycletime","g":"agile","word":"Cycle time","text":"How long a card takes from when work really starts on it to when it is finished.","also":["cycle times"]},{"id":"throughput","g":"agile","word":"Throughput","text":"How many cards get finished in a week, or in any set time.","also":["throughput rate"]},{"id":"bottleneck","g":"agile","word":"Bottleneck","text":"The one stage where work piles up and slows everything behind it, like the narrow neck of a bottle.","also":["bottlenecks"]},{"id":"swimlane","g":"agile","word":"Swimlane","text":"A row across the board that groups cards of one kind, such as urgent work or one team’s cards.","also":["swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"A way of working that cuts out waste (anything that doesn’t help the customer) and keeps work flowing."},{"id":"waste","g":"agile","word":"Waste","text":"In Lean, anything that takes effort but doesn’t help the customer, like waiting, rework or building things nobody uses.","noTip":1},{"id":"kaizen","g":"agile","word":"Continuous improvement","text":"Getting a little better all the time through small regular changes, then checking they helped. Retros are one way to do it. Also called kaizen.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Self-organising team","text":"A team that decides for itself how to do the work, rather than being told step by step.","also":["self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Cross-functional team","text":"A team that has all the skills it needs to finish the work itself, like design, building and testing.","also":["cross-functional"]},{"id":"spike","g":"agile","word":"Spike","text":"A short, timeboxed bit of research to answer a question before committing to the real work.","also":["spikes"]},{"id":"rework","g":"agile","word":"Rework","text":"Doing work again because it wasn’t right the first time.","also":["reworked"]},{"id":"safe","g":"agile","word":"Scaled Agile (SAFe)","text":"Ways of using Agile across many teams in a big organisation. SAFe (the Scaled Agile Framework) is one well known example.","also":["SAFe","scaled Agile"]},{"id":"repo","g":"build","word":"儲存庫","text":"專案的程式碼資料夾及其完整的 commit 歷史，通常也存放在 GitHub 上。","also":["repository","Repo","repo"]},{"id":"branch","g":"build","word":"分支","text":"程式碼中一條獨立的工作線，這樣就能在不動主版本的情況下做變更。","also":["branches","Branch"]},{"id":"commit","g":"build","word":"Commit","text":"程式碼的一次已儲存快照，附有一句變更說明。你隨時可以回到某一個快照。","also":["commits","提交"]},{"id":"push","g":"build","word":"Push","text":"把已儲存的快照（commit）從這台電腦傳送到 GitHub，這樣它們就有了備份並可共用。"},{"id":"merge","g":"build","word":"合併","text":"把一個分支的變更併回主版本。"},{"id":"pr","g":"build","word":"Pull Request","text":"請求檢查某個分支的變更並合併到主版本。","also":["PR"]},{"id":"refactor","g":"build","word":"重構","text":"在不改變功能的前提下整理程式碼：檔案更小、命名更清楚、重複更少。"},{"id":"bug","g":"build","word":"Bug","text":"某樣東西沒有照預期正常運作。","also":["bugs","錯誤"]},{"id":"peerreview","g":"build","word":"同儕審查","text":"多一雙眼睛：另一個 AI 會在每張卡片的工作送到你面前之前先檢查一遍，這樣漏掉的錯誤會更少。","also":["程式碼審查","peer review","code review"]},{"id":"code","g":"build","word":"Code","text":"The written instructions that tell a computer what to do. Also called source code.","also":["source code"],"noTip":1},{"id":"proglang","g":"build","word":"Programming language","text":"A language for writing code, such as JavaScript, Python or Java. Different ones suit different jobs.","also":["programming languages"]},{"id":"developer","g":"build","word":"Developer (dev)","text":"Someone who writes and changes code. Also called a programmer or software engineer.","also":["developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Software","text":"Programs that run on computers and phones, as opposed to the machines themselves (the hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Short for application: a program people use to get something done, on a phone, a computer or in a web browser.","also":["apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Web app","text":"An app that runs in a web browser, so there is nothing to install.","also":["web apps","web application"]},{"id":"frontend","g":"build","word":"Front end","text":"The part of an app you see and click on: the screens, buttons and words, often in your browser.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end","text":"The behind-the-scenes part of an app that keeps the data and does the work when you click something, like checking your password.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Working on both the front end and the back end.","also":["full-stack"]},{"id":"ui","g":"build","word":"User interface (UI)","text":"What a person sees and uses on screen: layout, buttons, menus and text.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"User experience (UX)","text":"How it feels to use something: easy, clear and pleasant, or confusing and slow.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Accessibility (a11y)","text":"Making things usable by everyone, including people who can’t see well, can’t use a mouse or use a screen reader.","also":["a11y"]},{"id":"responsive","g":"build","word":"Responsive design","text":"Making pages fit and work well on any screen size, from a phone to a big monitor.","also":["responsive"]},{"id":"designsys","g":"build","word":"Design system","text":"A shared kit of colours, fonts, buttons and rules, so every screen looks and behaves the same way.","also":["design systems"]},{"id":"architecture","g":"build","word":"Architecture","text":"The overall shape of a system: what the main parts are and how they talk to each other."},{"id":"database","g":"build","word":"Database (DB)","text":"An organised store of information, like a very powerful spreadsheet that the app can read and change.","also":["database","databases","DB"]},{"id":"schema","g":"build","word":"Database schema","text":"The layout of a database: which tables of information it has and what goes in each.","also":["schema"]},{"id":"sql","g":"build","word":"SQL","text":"Short for structured query language: the language used to ask many databases for information or to change it.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Data","text":"Information kept by a computer, like names, orders or settings.","also":["dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"A computer that is always on and answers requests from other computers, like sending a web page when you visit it.","also":["servers"]},{"id":"client","g":"build","word":"Client","text":"The side that asks for something, usually your browser or app, talking to a server. In business it also just means a customer.","also":["clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Short for application programming interface: a set menu of requests one program can make to another, like asking a weather service for today’s forecast.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"One item on an API’s menu: a web address a program can call to get or send something.","also":["endpoints"]},{"id":"integration","g":"build","word":"Integration","text":"Connecting two systems so they work together, like your shop sending orders to your accounts software.","also":["integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"A message one system sends to another by itself the moment something happens, like “payment received”.","also":["webhooks"]},{"id":"library","g":"build","word":"Library","text":"Ready-made code someone else wrote that you can reuse instead of writing it yourself.","also":["libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"A ready-made structure for building an app that decides much of how the code is laid out, like a house frame you fill in.","also":["frameworks"]},{"id":"sdk","g":"build","word":"Software development kit (SDK)","text":"A box of tools, code and examples for building software for one platform or service.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Software dependency","text":"A library or tool your code needs to work. Keeping them up to date matters for safety.","also":["software dependencies"]},{"id":"package","g":"build","word":"Package","text":"A bundle of ready-made code you can install and use in a project.","also":["packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Package manager","text":"A tool that fetches and updates the packages your code depends on. npm is a common one.","also":["package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"The most widely used tool for keeping the history of code changes, as commits and branches."},{"id":"github","g":"build","word":"GitHub","text":"A website that keeps Git repos online, so teams can share code, review changes and track work."},{"id":"vcs","g":"build","word":"Version control","text":"Keeping a full history of every change to the files, so you can see who changed what and go back if needed. Git does this.","also":["source control","version control system"]},{"id":"clone","g":"build","word":"Clone","text":"Making your own full copy of a repo, with its history, on your computer.","also":["cloned","cloning"]},{"id":"pull","g":"build","word":"Pull","text":"Fetching the latest commits from the shared copy (like GitHub) onto your computer. The opposite of push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Main branch","text":"The official version of the code that everyone works from, often called main or master.","also":["master branch"]},{"id":"conflict","g":"build","word":"Merge conflict","text":"When two changes touch the same lines in different ways, so the computer can’t join them and a person has to choose.","also":["merge conflicts"]},{"id":"diff","g":"build","word":"Diff","text":"A view showing exactly what changed between two versions: lines added and lines taken away.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Your own copy of someone else’s repo, which you can change without affecting theirs.","also":["forks","forked"]},{"id":"script","g":"build","word":"Script","text":"A short program that does one job by itself, like tidying files or starting the app.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Turning the code into something ready to run, or the ready-to-run result itself.","also":["builds"],"noTip":1},{"id":"compile","g":"build","word":"Compile","text":"Translating code people wrote into a form the computer can run directly.","also":["compiled","compiler","compiling"]},{"id":"cli","g":"build","word":"Command line (CLI)","text":"A text window where you type instructions for the computer instead of clicking. Also called the terminal.","also":["command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Configuration (config)","text":"The settings that control how software behaves, kept apart from the code so they are easy to change.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Environment variable","text":"A setting handed to a program when it starts, often used for addresses or passwords so they aren’t written into the code.","also":["environment variables","env var"]},{"id":"debugging","g":"build","word":"Debugging","text":"Hunting down why something isn’t working, and fixing it.","also":["debug","debugged"]},{"id":"pairing","g":"build","word":"Pair programming","text":"Two people (or a person and an AI) working on the same code together, one typing and one checking.","also":["pairing"]},{"id":"docs","g":"build","word":"Documentation (docs)","text":"Written explanations of how something works or how to use it.","also":["documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"The first file to read in a repo: what the project is and how to get it running.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Legacy system","text":"An older system still in use that is hard to change, often because few people still understand it.","also":["legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Technical debt","text":"Shortcuts that save time now but make later changes slower, like a loan that builds up interest. Refactoring pays it down.","also":["tech debt"]},{"id":"test","g":"test","word":"測試","text":"在你接受之前，試用一項完成的工作，檢查它是否符合要求。","also":["tests","Test"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"quality assurance（品質保證）的縮寫：任何東西上線前都會自動執行的檢查。QA 變紅就表示有檢查沒通過，修好之前不能上線。","also":["品質檢查","品質保證","quality assurance","quality checks"]},{"id":"testpile","g":"test","word":"測試堆疊","text":"等你來試的已完成卡片，一張接一張。接受一張，或附上說明退回去，下一張就會出來。","also":["test pile","test piles"]},{"id":"autotest","g":"test","word":"Automated test","text":"A check the computer runs by itself every time the code changes, to catch mistakes early.","also":["automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Manual test","text":"A person trying the work by hand to see if it behaves as it should.","also":["manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Unit test","text":"A small automatic check of one tiny piece of code on its own.","also":["unit tests"]},{"id":"integtest","g":"test","word":"Integration test","text":"A check that several parts work properly together, not just one at a time.","also":["integration tests"]},{"id":"endtoend","g":"test","word":"End-to-end test (E2E)","text":"A test that acts like a real user from start to finish, such as signing up, buying and paying.","also":["E2E","end-to-end","end-to-end tests"]},{"id":"uat","g":"test","word":"User acceptance testing (UAT)","text":"The people who asked for the work try it themselves and say whether it does what they need. AI-gile’s test pile is its version of this.","also":["UAT","acceptance testing"]},{"id":"regression","g":"test","word":"Regression","text":"Something that used to work but broke after a change. Regression tests check that the old things still work.","also":["regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Smoke test","text":"A very quick check that the main things work at all, for example right after a change goes live. If it fails, stop and look.","also":["smoke tests"]},{"id":"exploratory","g":"test","word":"Exploratory testing","text":"Trying the product freely and poking at it in different ways, to find problems that planned checks would miss.","also":["exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Test case","text":"One written scenario to try: the steps, and what should happen.","also":["test cases"]},{"id":"coverage","g":"test","word":"Test coverage","text":"How much of the code is checked by automatic tests. More is usually safer, but high coverage alone doesn’t prove it works well.","also":["coverage","code coverage"]},{"id":"testdata","g":"test","word":"Test data","text":"Made-up example information used while testing, so no real person’s private details are exposed.","also":["test fixtures"]},{"id":"edgecase","g":"test","word":"Edge case","text":"An unusual situation at the limits, like an empty form or a name with an apostrophe, where things often break.","also":["edge cases"]},{"id":"happypath","g":"test","word":"Happy path","text":"The normal route where everything goes right. Good testing also tries the unhappy paths."},{"id":"perftest","g":"test","word":"Performance testing","text":"Checking how fast something is and how well it copes under strain.","also":["performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Load testing","text":"Checking how a system copes when lots of people use it at once.","also":["load test","load tests"]},{"id":"sectest","g":"test","word":"Security testing","text":"Looking for weaknesses that could let someone misuse a system or see what they shouldn’t.","also":["security test","security tests"]},{"id":"accesstest","g":"test","word":"Accessibility testing","text":"Checking that people with different abilities can use the product, including with a screen reader or only a keyboard.","also":["accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"An automatic check that spots likely mistakes and messy style in code, like a spelling checker for programs.","also":["linter","lint"]},{"id":"static","g":"test","word":"Static analysis","text":"Checking code for problems by reading it automatically, without running it.","also":["static code analysis"]},{"id":"flaky","g":"test","word":"Flaky test","text":"A test that sometimes passes and sometimes fails for no clear reason, so it can’t be fully trusted.","also":["flaky tests"]},{"id":"repro","g":"test","word":"Reproduce (repro)","text":"Making a bug happen again on purpose by following the same steps, so it can be studied and fixed. Writing those steps down is the most useful part of a bug report.","also":["repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Severity","text":"How bad a problem’s effect is, from a small annoyance to everything stopping.","also":["severity level"]},{"id":"deploy","g":"change","word":"部署","text":"讓新版本上線，例如放到人們使用的伺服器上。"},{"id":"release","g":"change","word":"發行版本","text":"一批有名稱、一起上線的已完成工作，附上幾句簡短說明，講清楚改了什麼。🚀 發行版本 會根據已完成的卡片寫好這些說明。","also":["發布","發行","release","releases"]},{"id":"rollback","g":"change","word":"回滾","text":"新版本出問題時，退回到上一個正常運作的版本。在 AI-gile 裡，它會把每項變更上寫好的復原步驟整理成一份清單。","also":["回復上一版","rollback","roll back","roll-back","rolled back"]},{"id":"live","g":"change","word":"正式環境","text":"大家真正在用的那個版本，而不是拿來試東西的副本。把東西放上去就叫上線。開發者也叫它 production。","also":["上線","線上","production","live"],"noTip":1},{"id":"change","g":"change","word":"變更","text":"對大家依賴的東西所做的有計畫的修改，事先寫清楚：改什麼、為什麼、有什麼風險、什麼時候改、怎麼復原。用 🔀 提出變更 來開始。","also":["變更請求","change","change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"風險","text":"可能出錯的事，依發生的可能性和嚴重程度評分。⚠️ 風險 把它們放在同一個清單裡，分數最高的在最前面，每一項都有再次檢視的日期。","also":["風險登記","risk","risks","risk register"]},{"id":"chgwin","g":"change","word":"變更時段","text":"允許變更上線的時間，例如一個清閒的星期二晚上。在時段之外，變更卡片無法完成，除非是緊急狀況。","also":["變更窗口","change window","change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"變更上線前的一次快速表決：每個需要核准的人說 Go 或 No go。只有大家都同意才會繼續。","also":["go/no go","go-no-go","上線決策"]},{"id":"approval","g":"change","word":"核准","text":"開工前先等一聲「好」。朋友提出的卡片，或一項變更，會在 ✅ 核准 裡等著，直到你核准或拒絕。","also":["批准","審核","approval","approvals"]},{"id":"quiettime","g":"change","word":"安靜時段","text":"一段什麼都不上線的時間，例如直播、展示或深夜。團隊照常工作和測試，但上線要等它結束。在其他地方叫作變更凍結。","also":["變更凍結","封版","quiet time","quiet times","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"A way of working where the people who build software and the people who run it work as one team, with lots of automation, so changes go live often and safely."},{"id":"cicd","g":"change","word":"CI/CD (continuous integration and delivery)","text":"Everyone’s changes are joined into the main version often and checked automatically each time (continuous integration), so the software is always ready to go live at the press of a button (continuous delivery).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Continuous deployment","text":"One step further than continuous delivery: every change that passes the checks goes live by itself, with no button to press.","also":["continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"The automatic series of steps a change goes through on its way to live, like build, test, then deploy.","also":["pipelines"]},{"id":"environment","g":"change","word":"Environment","text":"One separate copy of the system for one purpose, such as one to build in, one to test in and the live one.","also":["environments"],"noTip":1},{"id":"devenv","g":"change","word":"Development environment","text":"The copy a developer works in, often on their own computer, where breaking things harms nobody.","also":["dev environment"]},{"id":"testenv","g":"change","word":"Test environment","text":"A separate copy of the system used just for testing, so the real service isn’t touched.","also":["test environments"]},{"id":"staging","g":"change","word":"Staging","text":"A last copy set up just like live, for a final check before a change goes live.","also":["staging environment"]},{"id":"artifact","g":"change","word":"Build artifact","text":"The file or bundle a build produces, ready to be stored, checked or put live.","also":["build artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"An urgent fix put live quickly, outside the normal plan, because something important is broken.","also":["hotfixes"]},{"id":"patch","g":"change","word":"Patch","text":"A small update that fixes a bug or closes a security hole. Applying security patches quickly matters.","also":["patches","security patch","security patches"]},{"id":"version","g":"change","word":"Version number","text":"A label like 2.4.1 that says which release you have. Often the first number changes for big changes and the last for small fixes.","also":["version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Release notes","text":"A short plain list of what changed in a release, for the people who use it, including fixes and known limits. Also called a changelog.","also":["changelog","change log"]},{"id":"flag","g":"change","word":"Feature flag","text":"An on and off switch for a feature, so new work can go live hidden and be turned on (or off again) without a new release.","also":["feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"Fixing a bad release by quickly putting out a new, corrected version instead of going back to the old one.","also":["rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Canary release","text":"Putting a change live for a small group first, and for everyone only once it looks fine. Named after the canaries miners took underground as an early warning.","also":["canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Blue-green deployment","text":"Keeping two copies of the live system and switching people over to the new one in one go, so you can switch straight back if it goes wrong.","also":["blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"Zero-downtime deployment","text":"Putting a new version live without the service ever stopping for its users.","also":["zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Change enablement","text":"Helping changes succeed: weighing the risk, getting the right approval and picking a good time. Also called change management.","also":["change management"]},{"id":"cab","g":"change","word":"Change advisory board (CAB)","text":"A group that looks over important changes and agrees whether and when they may go ahead.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Standard change","text":"A low-risk change done the same tried and tested way each time, so it is approved in advance.","also":["standard changes"]},{"id":"normchange","g":"change","word":"Normal change","text":"A change that needs to be checked and approved before it goes ahead.","also":["normal changes"]},{"id":"emergchange","g":"change","word":"Emergency change","text":"A change that must happen right away to fix or prevent serious trouble, with a quicker approval to match.","also":["emergency changes"]},{"id":"automation","g":"change","word":"Automation","text":"Getting the computer to do a repeated job by itself, so it is quicker and done the same way every time.","also":["automated"],"noTip":1},{"id":"infra","g":"change","word":"Infrastructure","text":"The machines, networks and services that software runs on.","also":["infra"]},{"id":"iac","g":"change","word":"Infrastructure as code (IaC)","text":"Describing your servers and settings in files kept with the code, so they can be rebuilt exactly the same way every time.","also":["IaC"]},{"id":"cloud","g":"change","word":"Cloud","text":"Renting computers, storage and services from a big provider over the internet, instead of owning the machines yourself.","also":["the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Cloud provider","text":"A company that rents out computing over the internet, such as Amazon Web Services (AWS), Microsoft Azure or Google Cloud.","also":["cloud providers"]},{"id":"hosting","g":"change","word":"Hosting","text":"Where your app or website lives and runs so people can reach it, usually rented from a company.","also":["hosted"]},{"id":"domain","g":"change","word":"Domain name","text":"The web address people type, like example.com. You rent it by the year, so it must be renewed.","also":["domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Short for domain name system: the internet’s address book, which turns a name like example.com into the address of the right computer.","also":["domain name system"]},{"id":"container","g":"change","word":"Container","text":"A sealed package holding an app and everything it needs, so it runs the same on any computer. Docker is the best known tool.","also":["containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtual machine (VM)","text":"A pretend computer running inside a real one, so one big machine can act as many.","also":["VM","VMs","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"Running code without looking after any servers yourself: the provider runs it when needed and you pay for what you use."},{"id":"lb","g":"change","word":"Load balancer","text":"Something that spreads visitors across several servers, so no single one gets overwhelmed.","also":["load balancers"]},{"id":"cache","g":"change","word":"Cache","text":"A handy store of recent results kept close by, so the same thing doesn’t have to be fetched or worked out again. Clearing it can fix pages that look out of date.","also":["caches","caching","cached"]},{"id":"cdn","g":"change","word":"Content delivery network (CDN)","text":"A worldwide set of servers holding copies of your pages and pictures near your visitors, so they load quickly.","also":["CDN"]},{"id":"migration","g":"change","word":"Migration","text":"Moving data or systems from an old setup to a new one, or carefully changing how a database is laid out.","also":["migrations","database migration"]},{"id":"service","g":"run","word":"服務","text":"你做出來、大家依賴的東西，例如網站或 App，有人照顧著讓它持續正常運作。勾選「此專案是一項服務」，再寫上它提供什麼、誰在用、誰值班。","also":["service","services"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"How much of the time a service is working, usually as a percentage. 99.9% still allows about 43 minutes down a month.","also":["uptime percentage"]},{"id":"uptime","g":"run","word":"可用性檢查","text":"每隔幾分鐘自動檢查一次你的服務是否還有回應。如果連續失敗幾次，AI-gile 會自己開一張事故卡片。","also":["上線時間","可用性","uptime","uptime check","uptime checks"]},{"id":"statuspage","g":"run","word":"狀態頁","text":"一個公開頁面，顯示服務是否正常（綠、橘或紅）以及最新進度，讓使用者自己查看，不必來問。","also":["狀態頁面","status page","status pages"]},{"id":"desk","g":"run","word":"服務台","text":"使用你服務的人提出的問題和回報都會送到這裡。AI-gile 會把每一則分類為請求、事故或想法，如果看起來跟已經回報過的東西很像，也會告訴你。","also":["服務台","客服台","help desk","helpdesk","service desk"]},{"id":"svcrequest","g":"run","word":"服務請求","text":"有人要的是一般的東西，例如新帳號或一點協助，而不是回報有東西壞了。它會排隊等候；事故優先處理。","also":["服務請求","請求","service request","service requests"]},{"id":"incident","g":"run","word":"事故","text":"此刻正影響使用者的故障，例如網站打不開。🔥 事故卡片會插隊：先讓它恢復正常再說。","also":["故障","incident","incidents"]},{"id":"major","g":"run","word":"重大事故","text":"大型事故：影響很多人，或金錢或資料有危險。一個按鈕就能讓所有團隊投入（蜂群），叫醒值班的人，並要求每 30 分鐘更新一次狀態。","also":["重大事件","major incident","major incidents"]},{"id":"oncall","g":"run","word":"值班","text":"就是出問題時負責回應的人，就算是半夜。每項服務都有一位值班的團隊成員，它的事故會最先叫醒這個人。","also":["值班人員","待命","on call","on-call"]},{"id":"replyby","g":"run","word":"回覆期限","text":"一張卡片最多能等多久得到第一次回覆，例如事故是一小時。超過之後它會出現紅色時鐘，免得有事被悄悄遺忘。也叫回應目標。","also":["回應目標","回應時間","reply-by time","response target","response targets"]},{"id":"postmortem","g":"run","word":"事後檢討","text":"事故之後的簡短回顧：發生了什麼、什麼有幫助、要改什麼，不追究任何人的責任。沒有事後檢討，事故就不能關閉。","also":["事故檢討","post-mortem","post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"問題","text":"一個或多個事故背後的隱藏原因。🧩 問題卡片會把反覆出現的事故歸在一起，好找出原因並徹底修好。","also":["problem","problems"],"noTip":1},{"id":"rootcause","g":"run","word":"根本原因","text":"東西壞掉的真正原因，而不只是你看到的表面故障。修好根本原因，事故就不會再回來。","also":["根因","root cause","root causes"]},{"id":"workaround","g":"run","word":"暫時解決辦法","text":"在真正的修正完成前讓東西繼續運作的辦法，例如卡住時重新啟動一下。它會寫在問題卡片上，這樣誰都不用再摸索一次。","also":["暫時方案","權宜之計","workaround","workarounds"]},{"id":"knownerror","g":"run","word":"已知錯誤","text":"原因已經弄清楚、也有暫時解決辦法，但還沒修好的問題。🧩 已知錯誤 把它們列出來，大家直接用暫時解決辦法，不必再重新追查。","also":["known error","known errors"]},{"id":"runbook","g":"run","word":"操作手冊","text":"處理某類已知問題的逐步說明，讓每次都用同樣的方式快速搞定。重大事故之後，團隊可以擬一份操作手冊，交給你確認。","also":["Runbook","runbooks","運行手冊"]},{"id":"ci","g":"run","word":"設定項目","text":"你的服務所依賴的某樣東西，例如伺服器、網域、憑證、金鑰或供應商。🗂️ 設定項目會按服務列出它們，讓你看出事故會影響到什麼，以及哪些東西需要續期或備份。","also":["設定項目","組態項目","configuration item","configuration items","CI"]},{"id":"expiry","g":"run","word":"到期日","text":"AI-gile 會留意各種日期，例如憑證或網域什麼時候到期。在到期前 30 天內，它會建立一張卡片提醒你續期，免得東西突然停擺。","also":["到期日","到期","到期提醒","expiry date","expiry dates","expiry"]},{"id":"backup","g":"run","word":"備份","text":"你的資料之前存下來的一份副本，萬一有東西遺失或損壞可以靠它。AI-gile 每天都會備份你的看板。","also":["backup","backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"還原","text":"從備份把資料放回去。只有確定能還原，備份才算真的有用，所以值得偶爾試一下。","also":["復原","已還原","restore","restored"]},{"id":"svcreview","g":"run","word":"服務回顧","text":"回頭看一項服務的一個月：開啟和修好的事故、大家多快得到回覆、正常運作時間，以及用掉的 token。月度檢討會為每項服務顯示這些內容。","also":["服務回顧","月度檢討","每月回顧","service review","monthly review"]},{"id":"accessreview","g":"run","word":"存取審查","text":"每 90 天檢查一次還有誰能進來：分享連結、朋友的角色，以及保存的密鑰。你逐一決定保留或移除，讓舊的存取權不會一直留著。","also":["存取審查","權限審查","access review","access reviews"]},{"id":"improvements","g":"run","word":"改進清單","text":"團隊決定要做得更好的所有事情，集中在一個地方：回顧會議的建議、檢討的行動項目和問題的修正，每一項都附上狀態。到 📈 改進 裡就能找到。","also":["改進清單","改進","improvement list","improvements"]},{"id":"tokencap","g":"run","word":"Token 上限","text":"一項服務的代理每月可用 token 的上限。到 80% 時你會收到警告；到 100% 時，它們的背景工作會等到下個月，或等你調高上限。","also":["token 上限","每月 token 上限","token cap","token caps"]},{"id":"svcmgmt","g":"run","word":"Service management","text":"Everything involved in keeping a service useful and working for the people who rely on it, day after day.","also":["managing a service"]},{"id":"itil","g":"run","word":"ITIL","text":"A widely used guide to good service management, covering things like incidents, problems and changes. The name once stood for IT Infrastructure Library."},{"id":"itsm","g":"run","word":"IT service management (ITSM)","text":"Running technology as a service for people, with clear ways to handle requests, incidents, changes and improvements.","also":["ITSM"]},{"id":"managed","g":"run","word":"Managed service","text":"A service someone else runs and looks after for you, under an agreement about how well it must work.","also":["managed services"]},{"id":"svcowner","g":"run","word":"Service owner","text":"The person who answers for a service as a whole: how well it works, what it costs and how it improves.","also":["service owners"]},{"id":"sla","g":"run","word":"Service level agreement (SLA)","text":"A written promise to customers about how well a service will work, like “up 99.9% of the time” or “answered within an hour”, often with money back if it is broken.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Service level objective (SLO)","text":"The team’s own target for how well a service should work over a period, usually set a bit stricter than the SLA to be safe.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Service level indicator (SLI)","text":"The actual measurement you check against a target, like the share of visits that loaded fine.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Availability","text":"Whether people can use a service when they need it, often measured as uptime.","also":["high availability"]},{"id":"downtime","g":"run","word":"Downtime","text":"Time when a service isn’t working or is switched off, planned or not.","also":["down time"]},{"id":"errorbudget","g":"run","word":"Error budget","text":"The small amount of failure your reliability target allows. While some is left you can take risks with changes; once it is used up, you slow down.","also":["error budgets"]},{"id":"outage","g":"run","word":"Outage","text":"A time when a service is down or badly broken for its users.","also":["outages"]},{"id":"degraded","g":"run","word":"Degraded","text":"Working, but badly: slow, or with some parts not working.","also":["degraded service"]},{"id":"monitoring","g":"run","word":"Monitoring","text":"Watching a service automatically all the time, so problems are spotted, ideally before users notice.","also":["monitored"]},{"id":"observability","g":"run","word":"Observability","text":"How well you can tell what is going on inside a system from the outside, using its logs, numbers and traces.","also":["o11y"]},{"id":"log","g":"run","word":"Log","text":"A running diary a program keeps of what it is doing, used to work out what went wrong.","also":["logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Trace","text":"A record of how one request travels through the different parts of a system, step by step, showing where it slowed down.","also":["traces","tracing"]},{"id":"latency","g":"run","word":"Latency","text":"How long something takes to answer, like the wait between clicking and the page appearing.","also":["lag"]},{"id":"alert","g":"run","word":"Alert","text":"An automatic message that something needs attention, like the website not answering.","also":["alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Alert fatigue","text":"When there are so many alerts that people start ignoring them, including the important ones.","also":["alarm fatigue"]},{"id":"dashboard","g":"run","word":"Dashboard","text":"A screen showing the most important numbers and statuses at a glance.","also":["dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Paging","text":"Urgently calling or waking the on-call person about a problem.","also":["paged"]},{"id":"escalation","g":"run","word":"Escalation","text":"Bringing in someone with more skill or authority when an issue can’t be sorted at the current level, or not fast enough.","also":["escalate","escalated"]},{"id":"triage","g":"run","word":"Triage","text":"Quickly sorting incoming issues by how urgent and important they are, so the worst gets handled first.","also":["triaged"]},{"id":"impact","g":"run","word":"Impact","text":"How much something affects people: how many, and how badly.","noTip":1},{"id":"urgency","g":"run","word":"Urgency","text":"How quickly something needs to be dealt with. Impact and urgency together set the priority.","noTip":1},{"id":"plevels","g":"run","word":"Priority levels (P1, P2…)","text":"Labels for how urgent an issue is. P1 is the most serious and needs action straight away.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Ticket queue","text":"The list of requests and incidents waiting to be picked up.","also":["ticket queues"]},{"id":"tiers","g":"run","word":"First line and second line","text":"Levels of support: first line takes the call and fixes simple things; second line has deeper skills for harder ones. Also called tier 1 and tier 2.","also":["first line","second line","first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Incident commander","text":"The one person who leads the response to an incident, so everyone knows who decides and who does what.","also":["incident commanders"]},{"id":"responsetime","g":"run","word":"Response time","text":"How long it takes before someone first picks up a request or incident.","also":["response times"]},{"id":"resolution","g":"run","word":"Resolution time","text":"How long it takes to fully sort out a request or incident, from report to fixed.","also":["resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Mean time to recover (MTTR)","text":"On average, how long it takes to get a service working again after it breaks. MTTR can mean slightly different things, so say what you measure.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Mean time between failures (MTBF)","text":"On average, how long a service runs before something breaks.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Configuration management database (CMDB)","text":"The list of all your configuration items and how they connect, so you can see what depends on what.","also":["CMDB"]},{"id":"asset","g":"run","word":"Asset","text":"Anything of value you own or pay for to run the service, like a laptop, a software licence or a domain.","also":["assets"],"noTip":1},{"id":"capplan","g":"run","word":"Capacity planning","text":"Making sure there will be enough computer power, storage and people for what is coming.","also":["capacity plan"]},{"id":"scaling","g":"run","word":"Scaling","text":"Coping with more users by giving a machine more power (scaling up) or adding more machines (scaling out).","also":["scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Business continuity","text":"Plans for keeping the important things going when something big goes wrong, like losing an office, a key supplier or the computers.","also":["business continuity plan"]},{"id":"dr","g":"run","word":"Disaster recovery (DR)","text":"The plan and tools for getting a service back after something serious, like losing a whole data centre.","also":["disaster recovery"]},{"id":"rto","g":"run","word":"Recovery time objective (RTO)","text":"The longest a service may be down after a disaster before it must be working again.","also":["RTO"]},{"id":"rpo","g":"run","word":"Recovery point objective (RPO)","text":"How much recent data you could afford to lose, measured in time. An RPO of one hour means backups at least every hour.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Redundancy","text":"Having spares ready, like a second server, so one failure doesn’t stop the service.","also":["redundant"]},{"id":"failover","g":"run","word":"Failover","text":"Switching over to a spare system by itself when the usual one fails.","also":["fail over"]},{"id":"spof","g":"run","word":"Single point of failure","text":"One part that takes everything down with it when it breaks, because there is no spare.","also":["single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Maintenance window","text":"A planned time when a service may be paused or slow for upkeep, announced to users in advance.","also":["maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Handover","text":"Passing work, knowledge and responsibility to another person or team, so nothing gets dropped.","also":["handovers","hand over"]},{"id":"kb","g":"run","word":"Knowledge base","text":"A collection of help articles and answers, for users and for the team.","also":["knowledge bases"]},{"id":"csat","g":"run","word":"Customer satisfaction (CSAT)","text":"A score from users saying how happy they were, often asked after a request is closed.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Supplier","text":"An outside company you rely on, like your hosting provider. Also called a vendor or third party.","also":["suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Service retirement","text":"Switching a service off for good, safely: telling its users, dealing with its data and access, and stopping its costs.","also":["retiring a service"]},{"id":"eol","g":"run","word":"End of life (EOL)","text":"When a product stops getting updates or support from its maker, so it should be replaced.","also":["EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"Cybersecurity","text":"Protecting systems and data from being broken into, stolen or damaged.","also":["cyber security"]},{"id":"authn","g":"sec","word":"Authentication","text":"Checking who someone is, usually with a password or a code. Often shortened to authn.","also":["authn"]},{"id":"authz","g":"sec","word":"Authorisation","text":"Checking what someone is allowed to do once you know who they are. Often shortened to authz.","also":["authz","authorization"]},{"id":"mfa","g":"sec","word":"Multi-factor authentication (MFA)","text":"Logging in with two or more proofs, like a password plus a code on your phone. Also called two-factor (2FA).","also":["MFA","2FA","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Single sign-on (SSO)","text":"Logging in once to get into many systems, like using your work account everywhere.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Password manager","text":"An app that creates strong passwords and remembers them for you.","also":["password managers"]},{"id":"secret","g":"sec","word":"Secret","text":"A password, key or other private code a program uses to get into something. It must never be shared or written into the code.","also":["secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API key","text":"A secret code that lets a program use another service’s API, and shows who is using (and paying for) it.","also":["API keys"]},{"id":"accesstoken","g":"sec","word":"Access token","text":"A temporary pass that proves a program is allowed in, so it doesn’t need your password each time. Not the same as an AI token.","also":["access tokens"]},{"id":"encryption","g":"sec","word":"Encryption","text":"Scrambling information so only someone with the right key can read it.","also":["encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"The secure way web pages travel, shown by the padlock in your browser, so nobody in between can read or change them."},{"id":"cert","g":"sec","word":"SSL/TLS certificate","text":"A digital ID card that lets a website prove who it is and use HTTPS. It expires, so it must be renewed.","also":["TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Permissions","text":"The rules for who may see or change what.","also":["permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Least privilege","text":"Giving each person or program only the access they truly need, for only as long as they need it.","also":["principle of least privilege"]},{"id":"rbac","g":"sec","word":"Role-based access control (RBAC)","text":"Giving access by role, like viewer or editor, rather than person by person.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Vulnerability","text":"A weakness that someone could use to break in or cause harm.","also":["vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"A weakness attackers know about before the makers have had any time to fix it.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware","text":"Harmful software, like viruses, made to damage, spy or steal.","also":["virus","viruses"]},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware that locks up your files and demands money to unlock them. Good backups are the best defence.","also":["ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Fake messages that try to trick you into giving away passwords or money, or opening something harmful.","also":["phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Social engineering","text":"Tricking people, rather than computers, into giving access, like a fake call from “IT support”."},{"id":"firewall","g":"sec","word":"Firewall","text":"A guard that decides which network traffic may come in or go out.","also":["firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Short for virtual private network: a private, scrambled link over the internet, often used to reach work systems safely.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Denial of service (DoS, DDoS)","text":"Flooding a service with so much fake traffic that real people can’t use it. DDoS means it comes from many computers at once.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Penetration test (pen test)","text":"Hiring friendly experts to try to break in, so weaknesses are found before real attackers find them.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Security audit","text":"A careful check of how well something is protected, against a list of good practice.","also":["security audits"]},{"id":"threatmodel","g":"sec","word":"Threat modelling","text":"Thinking through who might attack something, how, and what you would do to stop them.","also":["threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Data breach","text":"When private information gets out to people who shouldn’t have it, or is lost or changed without permission.","also":["data breaches"]},{"id":"pii","g":"sec","word":"Personal data","text":"Any information about a person who can be identified, like a name, email address or location. Also called PII.","also":["PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"The European law on personal data (the UK has its own version): collect only what you need, keep it safe, and let people see or delete theirs.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Data protection","text":"Looking after personal data properly and within the law.","also":["data protection law"]},{"id":"privacypolicy","g":"sec","word":"Privacy policy","text":"A public page saying what personal data you collect, why, and what you do with it.","also":["privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Consent","text":"A person’s clear, free yes to their data being used in a particular way. They can take it back at any time.","also":["opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"A small file a website saves in your browser to remember things, like being logged in. Some need your consent first.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Data minimisation","text":"Collecting and keeping only the personal data you really need for the job.","also":["data minimization"]},{"id":"retention","g":"sec","word":"Data retention","text":"How long data is kept before it is deleted. Keeping it no longer than needed is safer and often the law.","also":["retention period"]},{"id":"anon","g":"sec","word":"Anonymisation","text":"Changing data so nobody can reasonably be identified from it any more.","also":["anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Pseudonymisation","text":"Swapping names and other details for codes, with a key kept apart to link them back. It is still personal data.","also":["pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Data processing agreement (DPA)","text":"A contract saying how a supplier may handle personal data on your behalf.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Data protection impact assessment (DPIA)","text":"A careful look, before you start, at how a plan to use personal data could affect people and how to lower the risks.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Audit log","text":"A record of who did what and when, so actions can be checked later.","also":["audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Compliance","text":"Following the laws, rules and standards that apply to you, and being able to show that you do.","also":["compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"A well known international standard for managing information security. Companies can be certified against it.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"A US report, checked by outside auditors, showing a company looks after customer data properly.","also":["SOC2"]},{"id":"agent","g":"ai","word":"代理程式","text":"獨立處理任務的 AI：讀程式碼、做變更、執行檢查，並回報結果。","also":["agents","Agent","agent"]},{"id":"token","g":"ai","word":"Token","text":"AI 用量的計量單位：大約相當於讀寫的幾個字元。Token 越少，方案剩得越多。","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"一段會在設定時刻自動執行的小指令，例如 AI 工作階段開始時，這樣團隊才能聽到你的留言。","also":["hooks"]},{"id":"ai","g":"ai","word":"Artificial intelligence (AI)","text":"Computer systems that do things we usually think need a person, like writing, answering questions or recognising pictures.","also":["AI","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Machine learning (ML)","text":"A way of making computers learn patterns from lots of examples, instead of giving them exact rules.","also":["machine learning"]},{"id":"model","g":"ai","word":"Model","text":"The trained “brain” of an AI system, built by learning from huge numbers of examples. Models differ in skill, speed and price.","also":["models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Large language model (LLM)","text":"An AI model trained on vast amounts of text, so it can read and write language.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"Generative AI","text":"AI that creates new things, like text, pictures or code, rather than only sorting or spotting them.","also":["GenAI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"A program you talk with in everyday language, by typing or speaking.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"What you give an AI: your question or instructions, plus anything you hand it. Clearer prompts usually get better answers.","also":["prompts"]},{"id":"prompteng","g":"ai","word":"Prompt engineering","text":"The skill of writing prompts that get reliable, useful results.","also":["prompting"]},{"id":"sysprompt","g":"ai","word":"System prompt","text":"Background instructions an AI gets before the conversation starts, setting its role and rules. They weigh more than what you type.","also":["system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Context","text":"Everything the AI can see while it works: the instructions, your messages, files it has read and earlier replies.","noTip":1},{"id":"ctxwin","g":"ai","word":"Context window","text":"How much an AI can keep in mind at once, measured in tokens. Past that, older parts get dropped or summarised.","also":["context windows"]},{"id":"session","g":"ai","word":"Session","text":"One working conversation with an AI, from start to finish. A new session starts with a fresh memory.","also":["sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Memory","text":"Notes an AI keeps between sessions, so it remembers your preferences and past decisions.","noTip":1},{"id":"hallucination","g":"ai","word":"Hallucination","text":"When an AI says something that sounds sure of itself but is made up or wrong. Check important facts.","also":["hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Training","text":"Teaching a model by showing it huge numbers of examples, before anyone uses it.","also":["trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Training data","text":"The examples a model learned from. Its knowledge stops at the date that data was collected.","also":["training set"]},{"id":"cutoff","g":"ai","word":"Knowledge cutoff","text":"The date an AI’s built-in knowledge ends. It won’t know about later things unless it looks them up.","also":["training cutoff"]},{"id":"finetune","g":"ai","word":"Fine-tuning","text":"Extra training of an existing model on your own examples, to make it better at one particular job.","also":["fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inference","text":"An AI model actually being used to answer something, as opposed to being trained.","also":["model inference"]},{"id":"tooluse","g":"ai","word":"Tool use","text":"An AI being able to do things, not just talk: run commands, read files or search the web, through tools the app gives it.","also":["tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Subagent","text":"A helper AI that a main AI hands a smaller job to, and gets the result back from.","also":["subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Multi-agent","text":"Several AIs working together on one piece of work, each with its own part, like a small team.","also":["multi-agent system"]},{"id":"autonomy","g":"ai","word":"Autonomy","text":"How much an AI may do on its own before it has to ask a person.","also":["autonomous"]},{"id":"hitl","g":"ai","word":"Human in the loop","text":"Keeping a person involved to check or approve what the AI does at key points. In AI-gile that is you.","also":["human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Guardrails","text":"Limits and checks that keep an AI’s actions safe, like needing approval before anything goes live. They lower the risk of mistakes, but don’t rule them out.","also":["guardrail"]},{"id":"rag","g":"ai","word":"Retrieval-augmented generation (RAG)","text":"Letting an AI look things up in your own documents before it answers, so its answers rest on your facts.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Turning text into a list of numbers that captures its meaning, so a computer can find things that mean similar things.","also":["embeddings"]},{"id":"vectordb","g":"ai","word":"Vector database","text":"A database built to search those lists of numbers (embeddings), to find material with a similar meaning.","also":["vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"A common way to plug tools and data sources into AI apps, so an AI can use them.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperature","text":"A setting for how adventurous an AI’s answers are. Low gives steadier, more predictable answers; high gives more varied ones. Neither makes it always right.","also":["model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Able to work with more than one kind of information, such as text, pictures and sound.","also":["multi-modal"]},{"id":"evals","g":"ai","word":"Evaluation (eval)","text":"A planned test of how well an AI does on chosen examples, so you can compare models or prompts.","also":["eval","evals","evaluations"]},{"id":"bias","g":"ai","word":"Bias","text":"When an AI (or a person) leans unfairly one way, often because of what it learned from.","also":["biased"],"noTip":1},{"id":"responsible","g":"ai","word":"Responsible AI","text":"Using AI fairly, safely and honestly, with people still answerable for the results.","also":["ethical AI"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"A trick where hidden instructions in a web page or file try to make an AI do something its user didn’t ask for.","also":["prompt injections"]},{"id":"ratelimit","g":"ai","word":"Rate limit","text":"A cap on how many requests you may send to a service in a set time. Go over it and you have to wait.","also":["rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Usage limit","text":"How much AI work your plan allows in a period, after which it pauses or costs more.","also":["usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Building software mostly by describing what you want to an AI and letting it write the code.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Budget","text":"The amount of money set aside for something.","also":["budgets"],"noTip":1},{"id":"costest","g":"money","word":"Cost estimate","text":"A best guess at what something will cost before you start.","also":["cost estimates"]},{"id":"roi","g":"money","word":"Return on investment (ROI)","text":"What you get back compared with what you put in. If it is positive, it was worth it.","also":["ROI"]},{"id":"tco","g":"money","word":"Total cost of ownership (TCO)","text":"Everything something really costs over its whole life, not just the price to buy it: running, support, upgrades and finally retiring it.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx and OpEx","text":"CapEx is money spent up front on things you keep; OpEx is ongoing spending, like monthly bills.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Subscription","text":"Paying regularly, usually monthly or yearly, to keep using something.","also":["subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Software as a service (SaaS)","text":"Software you use online and pay for by subscription, while the maker runs it for you.","also":["SaaS"]},{"id":"payg","g":"money","word":"Pay as you go","text":"Paying only for what you use, like cloud computing or AI tokens.","also":["pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Overage","text":"Use above what your plan includes, which can cost extra.","also":["overages","overage charges"]},{"id":"billingalert","g":"money","word":"Billing alert","text":"A message when spending or use reaches a level you chose. It warns you, but doesn’t always stop further charges.","also":["billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Free tier","text":"A free level of a paid service, with limits. Handy for starting out.","also":["free plan"]},{"id":"pricing","g":"money","word":"Pricing plan","text":"The different packages a service sells, each with its own price and limits.","also":["pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licence","text":"The rules for how you may use, copy, change or share something someone else made, such as software, fonts or pictures.","also":["licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Open source","text":"Software whose code anyone can read, use and often change for free, under the rules of its licence.","also":["open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Open source licence","text":"The rules that come with open source code. Some let you do almost anything (like MIT); some ask you to share your changes too (like GPL).","also":["open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Proprietary","text":"Owned by a company and not free to copy or change. The opposite of open source.","also":["proprietary software"]},{"id":"copyright","g":"money","word":"Copyright","text":"The legal right of a creator to control copies of their work, including code and writing.","also":["copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Intellectual property (IP)","text":"Ideas and creations the law treats as owned, like code, designs, names and logos.","also":["intellectual property"]},{"id":"tos","g":"money","word":"Terms of service","text":"The rules you agree to when you use a service.","also":["terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Contract","text":"A written agreement between two sides that the law will back up.","also":["contracts"],"noTip":1},{"id":"sow","g":"money","word":"Statement of work (SOW)","text":"A document setting out exactly what work will be done, by when and for how much.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Fixed price","text":"An agreed price for the whole job, however long it takes.","also":["fixed-price"]},{"id":"tm","g":"money","word":"Time and materials","text":"Paying for the hours really worked and the things really used, rather than a set price.","also":["T&M"]},{"id":"invoice","g":"money","word":"Invoice","text":"A bill asking for payment for work done or goods supplied.","also":["invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Vendor lock-in","text":"When moving away from a supplier is so hard or costly that you are stuck with them.","also":["lock-in"]},{"id":"procurement","g":"money","word":"Procurement","text":"The process of choosing and buying from suppliers.","also":["purchasing"]},{"id":"servicecredit","g":"money","word":"Service credit","text":"Money back or a discount you get when a supplier misses its SLA.","also":["service credits"]}]}};
